from dataclasses import dataclass
from datetime import datetime
from typing import Optional


class ExpiredPromotionError(Exception):
    pass


@dataclass
class Promotion:
    code: str
    percent_off: int
    expires_at: datetime


def checkout_total(subtotal: float, promotion: Optional[Promotion], now: datetime) -> float:
    """Policy is provisional: an expired promotion rejects the order."""
    if promotion is None:
        return subtotal
    if now >= promotion.expires_at:
        raise ExpiredPromotionError(f"Promotion {promotion.code} has expired")
    return round(subtotal * (100 - promotion.percent_off) / 100, 2)
E
cat > test_checkout.py <<'E'
from datetime import datetime, timedelta
import pytest
from checkout import Promotion, ExpiredPromotionError, checkout_total

NOW = datetime(2026, 11, 16, 12)


def promo(delta):
    return Promotion("SAVE10", 10, NOW + delta)


def test_no_promotion():
    assert checkout_total(100, None, NOW) == 100


def test_valid_promotion_applies():
    assert checkout_total(100, promo(timedelta(days=1)), NOW) == 90


def test_expired_promotion_rejects_order():
    with pytest.raises(ExpiredPromotionError):
        checkout_total(100, promo(timedelta(days=-1)), NOW)


def test_expiry_instant_counts_as_expired():
    with pytest.raises(ExpiredPromotionError):
        checkout_total(100, promo(timedelta(0)), NOW)
E
python -m pytest -q 2>&1 | tail -3

